/* Current summaries; technical authority remains linked by full document path. */
function dossierLink(path,label){const i=DOSSIER.findIndex(d=>d.path===path);return i>=0?`<a href="#resources" data-document="${i}">${esc(label)}</a>`:'';}
function pitchCards(rows){return `<div class="pitch-grid">${rows.map(([n,t,b,status,gate])=>`<article class="pitch-card"><span class="pitch-index">${esc(n)}</span><h2>${esc(t)}</h2><p>${esc(b)}</p>${status?`<span class="pitch-status">${esc(status)}</span>`:''}${gate?`<p class="pitch-gate"><strong>Nghiệm thu:</strong> ${esc(gate)}</p>`:''}</article>`).join('')}</div>`;}
function currentPilotBudget(){const c=OVERVIEW_FLYWHEEL.cost;return calculateThesisBudget({...c,gpuHours:Object.values(c.gpuHours).reduce((a,b)=>a+b,0)});}
function nativeRunCard(){return `<section class="panel pitch-section"><div class="eyebrow">SELECTED NATIVE RUN · CHƯA THỰC THI</div><h2>Một recipe. Đủ đường dữ liệu và tham số.</h2>${table(['Thành phần','Thiết kế đang chọn','Contract / trạng thái'],PITCH_PAGES.nativeRun.map(r=>r.map(esc)))}<p>${dossierLink('docs/implementation-plan/skill-a1/01-native-task.md','Binding và native gate')} · ${dossierLink('docs/implementation-plan/skill-a1/02-recipes-and-data.md','Loss / modules / controls')}</p></section>`;}
function acquisitionReceiptView(){return `<section class="panel pitch-section"><div class="eyebrow">ACQUISITION DECISION RECEIPT · CONTRACT ĐỀ XUẤT</div><h2>Mỗi lần chọn dữ liệu để lại một lý do.</h2>${pitchCards(PITCH_PAGES.decisionSteps)}<p class="pitch-note">QA xác nhận mẫu hợp lệ; utility cần downstream gain và tổng công. Similarity hoặc số variants chưa là bằng chứng usefulness.</p><div class="pitch-links"><a href="data/skill-a1-plan/acquisition-decision.template.json" target="_blank" rel="noopener">Mẫu decision receipt ↗</a><a href="data/skill-a1-plan/release-quality.template.json" target="_blank" rel="noopener">Mẫu coverage / dedup receipt ↗</a></div></section>`;}
function monthProofView(){return `<section class="panel pitch-section" id="month-proof"><div class="eyebrow">POC 30 NGÀY · 13/10–11/11/2026</div><h2>Model học được. Robot chạy được. Dữ liệu có ích.</h2>${pitchCards(PITCH_PAGES.monthProof.map(([n,t,b])=>[n,t,b]))}<p class="pitch-note">Public task trước, robot BTC sau khi kiểm tương thích. RTX 3060 12GB + RTX 5090 đã có; robot/camera/collector và lịch truy cập chưa chốt. 16/20 là mục tiêu demo dự thảo, không chuẩn sản xuất.</p><a href="#roadmap">Bốn tuần và hardware gate →</a></section>`;}
function renderPitchPage(id,doc){const p=PITCH_PAGES.pages[id];let content='';
 if(id==='product')content=pitchCards([['01','Người dùng đầu tiên','Kỹ sư robot learning, cùng operator và task owner: thêm skill hoặc đổi điều kiện thao tác.'],['02','Một lượt làm việc','Chạy → kiểm giả thuyết → chọn repair/data → release → học → đo lại.'],['03','Đóng góp dự kiến','Decision receipts, dữ liệu dùng đúng objective và bằng chứng chất lượng–tổng công.']])+`<section class="panel pitch-section"><h2>Kế thừa gì, đội xây gì?</h2>${table(['Kế thừa','Đội xây / tích hợp','Phép đo giá trị'],[['FluxVLA lifecycle + pretrained VLA','A1 binding/scorer, releases, QA và decision workflow','Native useful baseline rồi source/workflow comparisons'],['Sim và dữ liệu nguồn đủ điều kiện','Coverage, masks, dedup, replay và loss routes','Full-task/regression; tổng công đến acceptance']])}<p><strong>Vì sao GR1?</strong> Research vehicle cho public-data pilot sim; hardware BTC có profile riêng. Công đoạn DENSO và lợi thế humanoid so với arm còn cần task owner xác nhận.</p></section>`+pitchCards(PITCH_PAGES.deliverables);
 if(id==='outcomes')content=monthProofView()+pitchCards(PITCH_PAGES.deliverables)+`<section class="panel pitch-section"><h2>Đã có bằng chứng gì?</h2><div class="pitch-split"><div><strong>Reference thu nhỏ đã chạy</strong><p>MuJoCo, idealized state, sequencer và predictor35×4; R0/12, S12/12, C0/12 final. C local pass nhưng không promote.</p><a href="#examples">Xem traces và receipts →</a></div><div><strong>Native MVP cần kiểm</strong><p>Policy GR1/A1, contact-valid grasp, human transfer và native savings còn cần receipts riêng.</p><a href="#validation">Xem acceptance draft →</a></div></div></section>`;
 if(id==='business'){const budget=currentPilotBudget(),usd=v=>v.toLocaleString('vi-VN',{style:'currency',currency:'USD'});content=`<section class="panel pitch-section" data-current-budget="pilot-sim"><span class="eyebrow">THAM KHẢO SIM TRƯỚC ĐÂY · A100 THUÊ</span><div class="pitch-budget"><strong>${usd(budget.total)}</strong><span>Subtotal phần đã tính · chưa tổng triển khai</span></div>${table(['Khoản','Công suất giả định','USD'],budget.lines.map(([l,v,sub])=>[esc(l),esc(sub),usd(v)]))}<p class="pitch-note">${esc(OVERVIEW_FLYWHEEL.cost.note)}</p><p>20 accepted roots / yield50% =40 attempts. Giá tham khảo kiểm ${esc(OVERVIEW_FLYWHEEL.cost.priceChecked)}; không phải quote DENSO hoặc forecast runtime. <a href="#overview">Điều chỉnh giả định trên trang Ý tưởng →</a></p></section>`+pitchCards([['01','Khả thi trước khi chốt lịch','Đo peak VRAM, batch/dtype/horizon/views và throughput; kiểm update/reload và learned closed-loop.'],['02','RunPlan tính theo jobs','R/R+S, seeds/repeats, steps, preprocessing/generation, eval/reset, retries và công người. 180 GPU-hours là cap, chưa bảo đảm job set hoàn tất.'],['03','Actual ledger quyết định saving','Tách setup/recurring work; tính cả rejects, QA, corrections và no-gain. Chỉ so khi cùng quality.']])+`<p class="pitch-links"><a href="data/skill-a1-plan/run-plan.template.json" target="_blank" rel="noopener">RunPlan cần measurements ↗</a><a href="data/skill-a1-plan/cost-ledger.template.csv" target="_blank" rel="noopener">Actual cost ledger ↗</a></p>`;}
 if(id==='roadmap')content=monthProofView()+`<section class="panel pitch-section"><h2>Đúng nhịp ba vòng của chương trình</h2>${table(['Mốc 2026','Vòng / hoạt động','Đội cần chuẩn bị'],PITCH_PAGES.contestTimeline.map(r=>r.map(esc)))}<p><a href="${esc(PITCH_PAGES.contestSource)}" target="_blank" rel="noopener">Lịch chính thức BTC ↗</a> · Kiểm 07/10/2026. Kế hoạch demo là đề xuất nhóm, không phải yêu cầu bắt buộc của BTC ở vòng 2.</p></section><ol class="pitch-timeline">${PITCH_PAGES.stages.map(([n,time,t,owner,body,gate])=>`<li><span class="pitch-index">${esc(n)}</span><div><small>${esc(time)} · ${esc(owner)}</small><h2>${esc(t)}</h2><p>${esc(body)}</p><p class="pitch-gate"><strong>Gate:</strong> ${esc(gate)}</p></div></li>`).join('')}</ol><section class="panel pitch-section"><h2>Robot là điều kiện của demo ngoài đời</h2><p>Phát triển từ public data ngay khi chờ BTC. Mốc 26/10 kiểm khả năng kịp hardware: robot/profile/camera/collector và recipe phải tương thích. Robot khác GR1 cần binding và adaptation riêng; sim pass chưa là physical pass.</p><p>FOCA, human video, World Models và nghiên cứu A1 8–12 tuần nằm sau PoC. Vòng 2 cần video demo tối đa 15 phút và pitch. Mentoring từ 20/10; sau thuyết trình củng cố 17–29/11, nộp 30/11 và demo trực tiếp 02/12.</p></section>`;
 if(id==='validation')content=monthProofView()+pitchCards(PITCH_PAGES.proofQuestions.map(([t,c,b],i)=>['0'+(i+1),t,c+' · '+b]))+`<section class="panel pitch-section"><h2>${esc(PITCH_PAGES.acceptance.label)}</h2><p>${esc(PITCH_PAGES.acceptance.rule)}</p>${table(['True success giả định','Xác suất vượt gate'],PITCH_PAGES.acceptance.power.map(r=>r.map(esc)))}<p class="pitch-note">${esc(PITCH_PAGES.acceptance.note)}</p><p>${dossierLink('docs/implementation-plan/skill-a1/04-evaluation-and-cost.md','Đọc sampling, power và source/workflow controls')}</p></section><section class="panel pitch-section"><h2>Final nằm ngoài vòng tune</h2><div class="pitch-flow"><span>Development: chọn / sửa / học</span><b>→</b><span>Freeze recipe + checkpoint + scorer</span><b>→</b><span>Fresh final → report / acceptance</span></div><p>Không chọn lại recipe trên final. Final cũ dùng cho vòng phát triển mới phải đổi vai trò và có final mới.</p></section>`;
 return head(p.eyebrow,p.title,p.lead)+engineeringScope()+`<div class="pitch-page">${content}<details class="technical-detail"><summary>Hồ sơ kỹ thuật và bằng chứng đầy đủ</summary><article class="document-reader">${renderMarkdown(doc.markdown,doc.path)}</article></details></div>`+next(p.next,p.nextLabel);
}
function renderResourceHub(){return head('HỒ SƠ & NGUỒN GỐC','Mỗi tài liệu.<br>Một vai trò rõ ràng.','Bản trình bày, recipe đề xuất và reference đã đo được phân biệt theo phạm vi.')+engineeringScope()+`<section class="panel pitch-section"><h2>Bản hiện hành để đọc và kiểm</h2><div class="pitch-grid">${PITCH_PAGES.authority.map(([t,a,b])=>`<article class="pitch-card"><h3>${esc(t)}</h3><p>${dossierLink(a,'Mở tài liệu chính →')}</p><p>${dossierLink(b,'Chi tiết / bằng chứng →')}</p></article>`).join('')}</div><p class="pitch-note">${esc(PITCH_PAGES.submission)}</p><div class="pitch-links"><a class="button" href="assets/idea-v3.1.zip" download>Tải hồ sơ + A1 + form + reference ↓</a><a href="data/denso-form-draft.md" download>Form draft Markdown ↓</a></div></section><section class="panel dossier-controls"><label for="document-select">Chọn tài liệu để đọc sâu</label><select id="document-select">${DOSSIER.map((d,i)=>`<option value="${i}">${esc(projectDisplayText(d.title))} · ${esc(d.path)}</option>`).join('')}</select><p class="small">IDEA/form là bản trình bày; A1 là recipe; engineering là chi tiết; review có ngày là lịch sử đánh giá, không kết quả thực nghiệm mới.</p></section><article id="document-reader" class="document-reader"></article>`;}
